    const IS_ISSUED_AT_REQUIRED: bool = true;
    const IS_RECIPIENT_REQUIRED: bool = true;
    const PAYLOAD_SCHEMA: Option<&'static str> = Some(
        "{\n  \"$defs\": {\n    \"ActionId\": {\n      \"description\": \"Opaque, community-minted identifier of one action. A consumer MUST NOT parse or order it; it is compared for equality only. Long enough to be unguessable, because a show of an id the caller may not see is answered `notFound` and an enumerable id would turn that answer into an oracle.\",\n      \"maxLength\": 128,\n      \"minLength\": 16,\n      \"pattern\": \"^[A-Za-z0-9._~:-]+$\",\n      \"title\": \"ActionId\",\n      \"type\": \"string\"\n    },\n    \"Ext\": {\n      \"additionalProperties\": true,\n      \"description\": \"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.\",\n      \"minProperties\": 1,\n      \"propertyNames\": {\n        \"pattern\": \"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+$\"\n      },\n      \"title\": \"Ext\",\n      \"type\": \"object\"\n    }\n  },\n  \"$id\": \"https://trusttasks.org/spec/vtc/members/authority-reduction-pending-notice/0.1\",\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"additionalProperties\": false,\n  \"description\": \"A community tells a subject that a reduction of their administrative authority has been requested and is cooling off: it will land at `landsAt` unless the administrator who requested it cancels it first. Sent when the reduction is parked, never when it lands — vtc/members/authority-reduced-notice reports the landing. The subject cannot block the reduction; the notice exists so that they learn of it before it takes effect. Unsolicited: the subject did not ask.\",\n  \"properties\": {\n    \"actionId\": {\n      \"$ref\": \"#/$defs/ActionId\",\n      \"description\": \"The cooling-off action holding the reduction. The subject follows it with vtc/admin/actions/show/0.2, where it appears with `callerRole: subject`, to learn whether it was cancelled or landed.\"\n    },\n    \"code\": {\n      \"description\": \"What will happen when the reduction lands. `revoked`: the subject's access control entry will be removed. `demoted`: its role will be changed to one with a lower ceiling. `narrowed`: its role will stay and what it allows will be reduced. The same set, with the same meanings, as vtc/members/authority-reduced-notice/0.1.\",\n      \"enum\": [\n        \"revoked\",\n        \"demoted\",\n        \"narrowed\"\n      ],\n      \"type\": \"string\"\n    },\n    \"decidedBy\": {\n      \"description\": \"DID of the administrator who requested the reduction — the only party who can cancel it before it lands. The community itself is the document's issuer.\",\n      \"minLength\": 1,\n      \"type\": \"string\"\n    },\n    \"did\": {\n      \"description\": \"The subject whose authority the pending reduction would reduce — the notice's recipient. Carried in the payload as well as the envelope so that a forwarded notice still names its subject.\",\n      \"minLength\": 1,\n      \"type\": \"string\"\n    },\n    \"ext\": {\n      \"$ref\": \"#/$defs/Ext\"\n    },\n    \"landsAt\": {\n      \"description\": \"When the reduction takes effect unless its requester cancels it first. Equal to the parked action's `landsAt`; fixed when the reduction was parked.\",\n      \"format\": \"date-time\",\n      \"type\": \"string\"\n    },\n    \"previousRole\": {\n      \"description\": \"The role the subject holds now, before the reduction lands.\",\n      \"maxLength\": 128,\n      \"minLength\": 1,\n      \"type\": \"string\"\n    },\n    \"reason\": {\n      \"description\": \"The requesting administrator's stated reason, verbatim. Absent when none was given; absent and empty are different claims.\",\n      \"maxLength\": 1024,\n      \"type\": \"string\"\n    },\n    \"requestedAt\": {\n      \"description\": \"When the reduction was requested and parked — not when the notice was sent.\",\n      \"format\": \"date-time\",\n      \"type\": \"string\"\n    },\n    \"resultingRole\": {\n      \"description\": \"The role the subject will hold once the reduction lands. Absent exactly when `code` is `revoked`.\",\n      \"maxLength\": 128,\n      \"minLength\": 1,\n      \"type\": \"string\"\n    }\n  },\n  \"required\": [\n    \"did\",\n    \"code\",\n    \"previousRole\",\n    \"decidedBy\",\n    \"requestedAt\",\n    \"landsAt\",\n    \"actionId\"\n  ],\n  \"title\": \"VTC Members Authority-Reduction-Pending Notice — payload\",\n  \"type\": \"object\"\n}\n",
    );
